// C->S PACKET DISPATCHER - PlrMsg.cpp
// Dispatch table: NET_D2GS_SERVER_INCOMING at 0x006E0D18 (103 entries, 8 bytes each)
// Entry: {fpHandler:4, bRequiresAlive:4}
// Handler: eD2ServerIncomingStatus __fastcall (SGAMEDATA*, D2UnitStrc*, char*, size_t)
// Alive-check bypass: opcodes 0x14, 0x15, 0x3C, 0x43, 0x66
// Dead-only: opcode 0x41 (Resurrect) checks for dead state
// Validates fpHandler with IsBadCodePtr before call.
eD2ServerIncomingStatus __fastcall NET_D2GS_SERVER_HandleIncomingPacketAfterClientCheck(::SGAMEDATA * pGame, D2UnitStrc * pUnit, char * pBytes, size_t nSize) {
    bool bModeCancelled;
    bool bHandlerInvalid;
    uint32_t nHighResTime;
    bool bAliveCheckPassed;
    int nCancelResult;
    uint8_t nOpcode;
    nOpcode = *pBytes;
    if (!nOpcode || nOpcode >= 0x67) {
      return SERVERSTATUS_BAD_PARAMS;
    }

    uint32_t nOpcodeIndex;
    nOpcodeIndex = (uint32_t)nOpcode;
    if (!NET_D2GS_SERVER_INCOMING[nOpcodeIndex].fpHandler) {
      return SERVERSTATUS_BAD_PARAMS;
    }

    switch (nOpcodeIndex) {
      case 0x14:

      case 0x15:

      case 0x3c:

      case 0x43:

      case 0x66:
        goto call_handler;
      default:
        nCancelResult = PlayerModes::PLRMODES_TryCancelModeAndMoveToLocation(pGame, pUnit, 1, 0, nullptr);
      bAliveCheckPassed = nCancelResult != 0;
      break;
      case 0x41:
        if (!pUnit) {
          return SERVERSTATUS_OK;
        }
      bAliveCheckPassed = pUnit->eAnimMode.ePlayerMode == eD2PlayerAnimMode_ns::Dead;
    }

    if (!bAliveCheckPassed) {
      return SERVERSTATUS_OK;
    }

    call_handler:
    if (pGame->dwLastActivityTime > 1) {
      nHighResTime = Fog::Src::LogManager::LOGMGR_GetHighResolutionTime();
      pGame->dwLastActivityTime = nHighResTime;
    }
    BOOL bAliveCheck = IsBadCodePtr((FARPROC)NET_D2GS_SERVER_INCOMING[nOpcodeIndex].fpHandler);
    if (bAliveCheck) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x19a4);
      exit(-1);
    }

    eD2ServerIncomingStatus eStatus = NET_D2GS_SERVER_INCOMING[nOpcodeIndex].fpHandler(pGame, pUnit, pBytes, nSize);
    return eStatus;
}

// Broadcasts a PvP kill-message (opcode 0x5a) to the game when a player is killed. Resolves the killer: if a monster, walks up to its owner player. Copies victim and killer names into fixed-length buffers (16 chars each); for monster killers it stores the boss number instead of a name. For player killers it encodes the killer's char name. Calls BroadcastEventMessage to send the assembled packet to all clients. Halts with an internal error if pVictim is not a player unit.
// @sourcefile .\PLAYER\PlrMsg.cpp
void __fastcall PLAYERMSG_BroadcastPlayerSlain(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * pVictim) {
    bool bIsChampion;
    int16_t nBossNo;
    D2UnitStrc* pOwnerUnit;
    D2ClientStrc* pClient;
    char* szCharName;
    uint32_t pVictimNameEnd;
    eD2UnitType eKillerType;
    D2Packet0x5aEventStructure packet0x5a;
    char szKillerNameTmp[16];
    int32_t nLine;
    if ((pVictim ? pVictim->eUnitType : UNIT_COUNT) != UNIT_PLAYER) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x19b4);
      exit(-1);
    }
    if (pUnit && pUnit->eUnitType == UNIT_MONSTER) {
      pOwnerUnit = Ai::AiGeneral::GetOwnerUnit(pUnit);
      if (pOwnerUnit && pOwnerUnit->eUnitType == UNIT_PLAYER) {
        pUnit = pOwnerUnit;
      }
    }

    memset(packet0x5a.szName1, 0, 16 * sizeof(packet0x5a.szName1[0]));
    memset(packet0x5a.szName2 + 4, 0, 12 * sizeof(packet0x5a.szName2[0]));
    packet0x5a.nPacketId = 'Z';
    packet0x5a.nMessageType = '\x06';
    packet0x5a.nColor = '\x04';
    if (!pUnit) {
      packet0x5a.nArg = -1;
    } else {
      packet0x5a.nArg = pUnit->nClassId;
    }

    packet0x5a.nArgTypes = '\x06';
    if (pUnit) {
      packet0x5a.nArgTypes = (uint8_t)pUnit->eUnitType;
    }

    memset(packet0x5a.szName2, 0, 4 * sizeof(packet0x5a.szName2[0]));
    pClient = UNIT::SUnit::SUNIT_GetClient(pVictim, ".\\PLAYER\\PlrMsg.cpp", 0x19c9);
    szCharName = GAME::Clients::GetCharName(pClient);
    pVictimNameEnd = Storm::Source::SSTR::SStrLen(szCharName);
    if (pVictimNameEnd) {
      Storm::Source::SSTR::SStrCopy(packet0x5a.szName1, szCharName, 0x10);
    } else {
      *(uint32_t*)(char*)&packet0x5a.szName1 &= -256;
    }

    eKillerType = UNIT_COUNT;
    if (pUnit) {
      eKillerType = pUnit->eUnitType;
    }

    switch (eKillerType) {
      case UNIT_PLAYER:
        {
          nLine = 0x10;
          pClient = UNIT::SUnit::SUNIT_GetClient(pUnit, ".\\PLAYER\\PlrMsg.cpp", 0x19db);
          szCharName = GAME::Clients::GetCharName(pClient);
          Storm::Source::SSTR::SStrCopy(szKillerNameTmp, szCharName, nLine);
          pVictimNameEnd = Storm::Source::SSTR::SStrLen(szKillerNameTmp);
          if (pVictimNameEnd) {
            Storm::Source::SSTR::SStrCopy(packet0x5a.szName2, szKillerNameTmp, 0x10);
          }

          break;
        }
      case UNIT_MONSTER:
        {
          pVictimNameEnd = Monsters::CheckMonsterType(pUnit, 2);
          if (pVictimNameEnd) {
            nBossNo = Monsters::GetBossNo(pUnit);
            packet0x5a.szName2[0] = (char)nBossNo;
            packet0x5a.szName2[1] = (char)((uint16_t)nBossNo >> 8);
          }

          break;
        }
    }

    BroadcastEventMessage(pGame, &packet0x5a);
    return;
}

void __fastcall SendPlayerStopAndAtributeUpdate(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2ClientStrc * pClient, int32_t nStopReason) {
    SendPlayerStop(pGame, pUnit, pClient, nStopReason);
    D2UnitStrc* pClientUnit = GAME::Clients::CLIENTS_GetControlUnit(pClient, 0);
    if (pUnit != pClientUnit) {
      return;
    }

    uint32_t nGoldLost = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_goldlost, 0);
    SendAttributeUpdate(pUnit, 0xaf, nGoldLost, pUnit);
}

